#!/usr/bin/env python3
"""Record one raw Jev reply, whole, into a committed file.

`jev.ask()` keeps `answers` and `usage` and drops the rest, so until this
file existed no harness had ever stored what the endpoint actually returns.
Two things in docs/design/tet-verifier-jev.md rested on a live call nobody
could re-read: the reply's top-level shape, and the versioned model the
alias `jev-latest` resolves to. This writes both down.

The request asks the two primitives the design uses — `noul` and `choice` —
over the same state as jev.py's smoke test. The key is read the way jev.py
reads it and goes only into the Authorization header; neither the request
headers nor the key are written anywhere.

    python3 record_reply.py            # writes jev_reply_<UTC date>.json
"""

import datetime, json, sys, urllib.request
from pathlib import Path

HERE = Path(__file__).parent
sys.path.insert(0, str(HERE))
import jev  # noqa: E402

REQUEST = {
    "state": "The build failed. Exit code 1. Three tests errored in payments/.",
    "model": jev.MODEL,
    "questions": {
        "failed": {"type": "noul", "instructions": "The build failed.",
                   "criteria": {"true": "it failed", "false": "it passed"}},
        "area": {"type": "choice", "instructions": "Which area do the errors sit in?",
                 "criteria": {"payments": "payment code", "auth": "login code",
                              "search": "search code"}},
    },
}


def main():
    req = urllib.request.Request(
        jev.ENDPOINT, data=json.dumps(REQUEST).encode(), method="POST",
        headers={"Authorization": f"Bearer {jev.api_key()}",
                 "Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=60) as r:
        reply = json.loads(r.read())
    now = datetime.datetime.now(datetime.timezone.utc)
    out = HERE / f"jev_reply_{now:%Y-%m-%d}.json"
    out.write_text(json.dumps({
        "recorded_at": now.isoformat(timespec="seconds"),
        "endpoint": jev.ENDPOINT,
        "request": REQUEST,
        "reply": reply,
    }, indent=1) + "\n")
    print(f"wrote {out.name}: top-level keys {sorted(reply)}, model {reply.get('model')!r}")


if __name__ == "__main__":
    main()

//! Does a fact's note talk about somewhere it never looked?
//!
//! # The check this recovers
//!
//! The project's flagship check was once `Domain ⊆ Extent` — compare what
//! a claim says it ranges over against what its evidence examined. It was
//! abandoned as vacuous: when one author supplies both sides, they come
//! out byte-identical ~80% of the time, no better than hand-authored
//! rows. Independence, not capture, was what moved that number.
//!
//! This is the same comparison in a form where independence is
//! structural rather than procedural. A fact's **extent is captured by
//! the tool** — `look` and `run` record what they actually opened, and
//! there is deliberately no flag to type one in. A fact's **note is
//! authored**. Those are two different acts by construction, so comparing
//! the locations a note *names* against the extent that was *captured*
//! cannot be made vacuous by one author writing both sides.
//!
//! # The failure it was written for
//!
//! From the first real memo authored through this tool, verbatim:
//!
//! ```text
//! F6  extent: audit_utils.rs 785-817
//!     note:  "...graph_utils::parents (graph_utils.rs ~560-566) reads a
//!             stored commit-graph record's parents when present, else
//!             falls back to object_utils::load_parcel(hash)?.parents
//!             directly -- the same parents field ... (no separate,
//!             potentially-diverging source)."
//! ```
//!
//! The note names two branches and concludes there is one source, about a
//! file the fact never opened. A second fact overreached the same way,
//! the two contradicted each other, and a claim leaned on both by name.
//! Nothing in the tool noticed, because nothing compared a note against
//! its own extent.
//!
//! # What this is not
//!
//! It is a **scope** check, never a truth check. Whether the note is
//! *correct* about the location it names is exactly the limit this
//! project registered as permanently out of reach ("insincere
//! examination" — capture makes the extent honest, not the
//! interpretation). Nothing here touches that.
//!
//! It is also **human-owed, never a refusal**. A note may legitimately
//! name a location as context, contrast, or a pointer to what to read
//! next, and only a person can tell that from an unsupported inference.
//! Refusing would make the honest case unwritable to catch the dishonest
//! one.
//!
//! # What it catches, measured, and what it does not
//!
//! Of the two overreaching facts in the memo that motivated it, this
//! catches **one**. F6 named a file and a line range (`graph_utils.rs
//! ~560-566`) it never opened, which is the strong tell and fires here.
//! F7's note asserted the client "mirrors the server's" walk while its
//! extent covered only the client — an overreach that names no location
//! at all, and so is invisible to any check of this shape.
//!
//! One refinement was tried and rejected on the evidence: flagging a
//! `module::symbol` reference whose module never appears in the fact's
//! own captured output. Measured against the same three facts, it would
//! have flagged a legitimate quotation (F3 citing `object_utils::
//! load_parcel`, a call site inside the code it did read) while missing
//! both real overreaches, because `graph_utils` and `merge_utils` do
//! appear in the read source as call sites. Naming a symbol the code you
//! read calls is normal; concluding about what that symbol *does* is the
//! failure — and those two are not distinguishable by string matching.
//!

/// This is the authoring surface agents actually use, so a finding that
/// only reached `check` would only ever reach the human reviewing the
/// finished memo — after the note, the claim resting on it, and the
/// prose are all written. The author is the one who can still cheaply
/// tell context from conclusion, and they get it here.
///
/// Carried as `attention`, a top-level array, rather than folded into a
/// prose sentence: the caller is a program, and a field it can branch on
/// beats a string it has to notice. `advice` is shared verbatim with the
/// CLI so the two surfaces cannot drift into saying different things
/// about the same finding.
fn fact_result(
    dir: &Path,
    id: &str,
    action: &str,
    folded: Vec<String>,
    refused: Vec<String>,
) -> serde_json::Value {
    let attention: Vec<serde_json::Value> = crate::scope::for_fact(dir, id)
        .iter()
        .map(|o| {
            json!({
                "kind": "note-outside-extent",
                "mentioned": o.mentioned,
                "extent": o.extent_labels,
                "guidance": crate::scope::advice(o),
            })
        })
        .collect();
    // `refused` answers a different question from `folded`: not what this
    // mint took, but what the author tried and could not do in the window
    // that produced it. A caller that folded one leftover observation
    // after two refused `look` calls can see both here, which is the
    // whole of the incident this was built for.
    json!({
        "id": id,
        "action": action,
        "attention": attention,
        "folded": folded,
        "refused_since_previous_fact": refused,
    })

            "output": outcome.printed,
        }))),
        Err(e) => Ok(refusal("run", &p.workspace, e)),
    }
}

#[tool(description = "Mint a fact from the pending buffer (refuses on an empty buffer — run `look`/`run` first), or `revise` an existing fact's note (extent/output/pin were set once at mint time and are never revised). Check the `attention` array in the result: a non-empty entry means your note names a location this fact's extent does not cover — read that location and mint a fact for it, or revise the note, rather than leaving a conclusion about code you did not open. The result also carries `folded` (what this mint took from the pending buffer, with ages) and `refused_since_previous_fact` (what was refused in the window that produced it, verbatim) — a refused `look` leaves the buffer untouched, so if you expected to fold a file and see a refusal instead, that is where it went. `workspace` is required (never defaulted); minted ids (F#) are workspace-relative only.")]
async fn fact(&self, Parameters(p): Parameters<FactParams>) -> Result<CallToolResult, ErrorData> {
    let dir = open_workspace(&p.workspace)?;
    let req = match p.revise {
        Some(id) => facts::FactRequest::Revise { id, note: p.note, why: p.why },
        None => facts::FactRequest::Mint { note: p.note },
    };
    // Both described before dispatch: a successful mint clears the
    // buffer and becomes the new window boundary.
    let folded = crate::pending::load(&dir)
        .map(|b| facts::describe_buffer(&b, workspace::now_unix()))
        .unwrap_or_default();
    let refused = facts::refusals_since_last_mint(&dir);
    match facts::dispatch(&dir, req) {
        Ok(facts::FactOutcome::Minted(f)) => {
            Ok(CallToolResult::structured(fact_result(&dir, &f.id, "minted", folded, refused)))
        }
        Ok(facts::FactOutcome::Revised { id }) => Ok(CallToolResult::structured(fact_result(
            &dir,
