/// Every refusal this workspace recorded since its last mint, verbatim.
///
/// # Why a mint reports what it could not do
///
/// [`describe_buffer`] says what a mint *folded*. It cannot say why what
/// the author expected to fold is missing — and that gap is the whole
/// incident this exists for: two `look` calls were refused for a
/// malformed line range, each left the pending buffer untouched, and the
/// next mint folded a leftover observation from an earlier line of
/// enquiry. The author saw a folding line with an age on it and nothing
/// else. The refusals had happened, and nothing the tool ever consults
/// had recorded them.
///
/// So the two halves are complementary and both are needed: what was
/// folded, and what was refused in the window that produced it. Neither
/// is a refusal itself, neither is counted, and neither carries a
/// threshold — a mint following a refusal is often entirely correct.
///
/// One helper, called by both surfaces, so CLI and MCP cannot drift on
/// which refusals a mint reports.
pub fn refusals_since_last_mint(workspace_dir: &Path) -> Vec<String> {
    workspace::refusals_since(workspace_dir, last_mint_timestamp(workspace_dir))
}

/// One fact's mint window: the refusals recorded between the previous
/// mint and this one.
pub struct MintWindow {
    pub fact_id: String,
    pub refusals: Vec<String>,
    /// The first fact in the workspace, whose window has no previous mint
    /// to open at and so runs from the beginning of the log.
    pub is_first: bool,
    /// At least one of these refusals shares a second with a mint
    /// boundary, so it cannot be placed on one side of it. Such a refusal
    /// appears in both adjacent windows — the same `>=` choice the
    /// mint-time replay makes, for the same reason: showing twice is
    /// recoverable, hiding once is the incident this exists for.
    pub straddles_a_boundary: bool,
}

/// Every fact whose mint window contains a refusal, in mint order.
///
/// # Why this exists beside the mint-time line
///
/// [`refusals_since_last_mint`] prints at the moment of minting, and that
/// is the only moment the defect is *preventable* rather than merely
/// discoverable — a fact's extent is unrevisable, so nothing later can
/// correct the evidence, only the note.
///
/// But a line printed at a terminal works only if it is read in the
/// moment, and a memo built on a bad fact otherwise renders and checks
/// clean. This recovers the same signal at grading time, when nobody is
/// relying on the author's attention: `FactEvent::Create` carries a
/// timestamp that ships in `facts.jsonl`, and the snapshot copies
/// `refusals.log` beside it, so the windows are derivable from files
/// every snapshot already contains. No schema change, nothing new stored.
///
/// Human-owed and verbatim: a mint following a refusal is frequently
/// correct, and which of them matters is a reader's call. Nothing here
/// counts, scores or ranks.
///
/// The listing is only ever as complete as the log beneath it — a
/// snapshot written by a build that did not record surface-layer
/// refusals simply has fewer lines, and this is silent about them. That
/// is not a completeness claim in either direction: a verbatim listing
/// asserts only what was recorded.
pub fn mint_windows(snapshot_dir: &Path) -> Vec<MintWindow> {
    let Ok(events) = workspace::read_jsonl::<FactEvent>(&log_path(snapshot_dir)) else {
        return Vec::new();
    };
    let mints: Vec<(String, u64)> = events
        .iter()
        .filter_map(|e| match e {
            FactEvent::Create { id, timestamp, .. } => Some((id.clone(), *timestamp)),
            FactEvent::Revise { .. } => None,
        })
        .collect();

    let mut out = Vec::new();
    for (i, (id, minted_at)) in mints.iter().enumerate() {
        // The window opens at the previous mint — or at the beginning of
        // the log for the first fact, which owns everything refused
        // before it.
        let opened = if i == 0 { None } else { Some(mints[i - 1].1) };
        let stamped: Vec<(u64, String)> = workspace::refusals_since(snapshot_dir, opened)
            .into_iter()
            .filter_map(|line| {
                let ts = line.split_once('\t').and_then(|(ts, _)| ts.parse::<u64>().ok())?;
                (ts <= *minted_at).then_some((ts, line))
            })
            .collect();
        if !stamped.is_empty() {
            let straddles_a_boundary = stamped
                .iter()
                .any(|(ts, _)| *ts == *minted_at || opened.is_some_and(|o| *ts == o));
            out.push(MintWindow {
                fact_id: id.clone(),
                refusals: stamped.into_iter().map(|(_, line)| line).collect(),
                is_first: i == 0,
                straddles_a_boundary,
            });
        }
    }
    out
}

/// Mint a fact from the current pending buffer. Refuses if the buffer
/// is empty (a fact needs a preceding `look`/`run`) or the note text is
/// empty. Clears the buffer on success, exactly once, after the log
/// append succeeds — never before.
pub fn mint(workspace_dir: &Path, note: &str) -> Result<Fact, AuthoringError> {
    if note.trim().is_empty() {
        return Err(workspace::refuse(workspace_dir, "fact", "note text is empty"));
    }
    let buf = pending::load(workspace_dir)?;
    if buf.is_empty() {
        return Err(workspace::refuse(
            workspace_dir,
            "fact",
            "pending observation buffer is empty; run `tetel look` or `tetel run` first, then `tetel fact`",
        ));
    }

    let extent: Vec<ExtentEntry> = buf

    for claim in claims {
        let records: Vec<&EvidenceRecord> = evidence.iter().filter(|e| e.claim_id == claim.id).collect();

        // A record grades a *proposition*, not an id. The digest of the
        // text it graded is written into every record; comparing it to
        // the claim's current text is what stops evidence transferring to
        // a rewritten claim.
        //
        // Without this, revising a proposition through the ordinary
        // `claim --revise` + `render --out` path left its old evidence
        // attached — including to the exact negation of what was graded,
        // with the memo still matching its snapshot, no drift, and the
        // machine partition clean.
        //
        // **Whether a stale record fails depends on what sits beside it.**
        // The first version of this check failed on any stale record, and
        // that was undischargeable: the evidence log is append-only with
        // no supersession, so re-grounding — the remedy this very check
        // printed — added a current record and left the failure standing.
        // A red nobody can clear is the defect this crate rejected in the
        // verdict-disagreement check hours earlier, rebuilt here.
        //
        // So: a claim with no record matching its current text is a
        // machine failure, because nothing grades what it now says. A
        // claim that has one is grounded, and its superseded records are
        // history — worth printing, never a failure. Re-grounding is now
        // a remedy that works.
        let current = crate::evidence::sha256_hex(&claim.proposition);
        let (fresh, stale): (Vec<&&EvidenceRecord>, Vec<&&EvidenceRecord>) = records
            .iter()
            .filter(|r| !r.proposition_digest.is_empty())
            .partition(|r| r.proposition_digest == current);

        for r in &stale {
            let line = format!(
                "{} — evidence from pass {} graded different text than this claim now carries \
(recorded digest {}…, current {}…).\n      that pass said: {} — {}",
                claim.id,
                r.pass,
                &r.proposition_digest[..r.proposition_digest.len().min(12)],
                &current[..current.len().min(12)],
                r.verdict,
                r.note.as_deref().unwrap_or("(no note)"),
            );
            if fresh.is_empty() {
                out_of_proof.push(format!(
                    "{line}\n      Out of proof: nothing grades what this claim says today. \
Reprove it against the current wording, or restore the wording it was graded against."
                ));
            } else {
                superseded.push(format!(
                    "{line}\n      Superseded by a later proof: {} record(s) grade the current \
wording. Kept because it is what an earlier pass actually found, and the log is append-only.",
                    fresh.len()
                ));
            }
        }

        if records.is_empty() {
            ungrounded.push((claim.id.clone(), claim.proposition.clone()));
            continue;
        }

        // Every check below asks what the evidence says about *what this
        // claim says now*, so every one of them reads this set rather
        // than `records`.
        //
        // Making only the stale/superseded partition digest-aware and
        // leaving the verdict checks comparing all records was the same
        // defect one layer down, and it punished exactly the loop this
        // crate exists to produce: a pass refutes a claim, the author
        // fixes the wording, a later pass grounds the new wording
        // unanimously — and `verdict-disagreement` still fired, forever,
        // on a supports/refutes pair against text that no longer exists.
        // The only escape was withdrawing the claim and re-issuing it
        // under a fresh id, which erases the refutation from the rendered
        // ledger — the one trail the loop exists to preserve. An
        // undischargeable red that can only be cleared by destroying
        // evidence is worse than the one it replaced.
        //
        // A record with no digest at all predates the field. It is
        // treated as grading the current text rather than dropped:
        // dropping it would silently retire these checks for every
        // document written before digests existed, turning a live
        // contradiction into a clean report. Grandfathering can at worst
        // report a disagreement that a revision has since resolved —
        // which is the direction that fails loudly.
        let grading_current: Vec<&EvidenceRecord> = records
            .iter()
            .copied()
            .filter(|r| r.proposition_digest.is_empty() || r.proposition_digest == current)
            .collect();

        // Distinct from "ungrounded": at least one record grades the
        // current text, and every one that does derives to `Attested` for
        // standing purposes. Today that's unconditionally true — ingestion
        // is the only write path, and `derived_kind` never returns
        // anything else for an ingested record — but the check is written
        // against `derived_kind`, not against "has any evidence", so it
        // keeps working once a witnessed grounding can also land here.
        //
        // The emptiness guard is not redundant: a claim whose records all
        // grade superseded text has already been reported as a machine
        // failure by the partition above, and `all` over nothing is true,
        // so without it that claim would also be announced as grounded.
        if !grading_current.is_empty() && grading_current.iter().all(|r| r.derived_kind() == Kind::Attested) {
            attested_grounded.push((claim.id.clone(), claim.proposition.clone()));
        }

        // A contradiction is `supports` *and* `refutes` on one
        // proposition — P and not-P, decidable without a human, which is
        // what belongs in the machine partition.
        //
        // Two things this deliberately no longer does.
        //

//! `tetel brief` — the grounding brief: every claim's id and proposition,
//! byte-identical to the ledger cell it came from, with `domain`/`extent`
//! withheld entirely so an independent grounding pass can't see what the
//! author declared the claim ranges over. `BriefItem` carries no field a
//! scope could leak through — that's enforced by its shape, not by care
//! at render time.

use serde::Serialize;

use crate::ledger::Claim;

pub struct BriefItem {
    pub id: String,
    pub proposition: String,
    pub pin: Option<String>,
}

/// Every ledger claim, unconditionally — including one already grounded,
/// and including one grounded only by ingested (attested-derived)
/// evidence. Ingestion enrolls a claim in the independent-grounding loop;
/// it does not excuse it, so nothing here may drop a claim from the brief
/// on account of what its evidence ledger already holds. A claim leaves
/// this list only by leaving the ledger itself — never by having been
/// reported on.
pub fn build(claims: &[Claim]) -> Vec<BriefItem> {
    claims
        .iter()
        .map(|c| BriefItem {
            id: c.id.clone(),
            proposition: c.proposition.clone(),
            pin: c.pin.clone(),
        })
        .collect()
}

pub fn render_text(display_path: &str, items: &[BriefItem]) -> String {
    let mut out = String::new();
    out.push_str(&format!(
        "grounding brief: {display_path} — {} claim(s), scope withheld\n\n",
        items.len()
    ));
    for item in items {
        out.push_str(&format!("id: {}\n", item.id));
        out.push_str(&format!("proposition: {}\n", item.proposition));
        if let Some(pin) = &item.pin {
            out.push_str(&format!("pin: {pin}\n"));
        }
        out.push_str("scope: WITHHELD\n\n");
    }
    out
}

#[derive(Serialize)]
struct JsonItem<'a> {
    id: &'a str,
    proposition: &'a str,
    #[serde(skip_serializing_if = "Option::is_none")]
    pin: Option<&'a str>,
    scope: &'static str,
}

pub fn render_json(items: &[BriefItem]) -> String {
    let json_items: Vec<JsonItem> = items
        .iter()
        .map(|i| JsonItem {
            id: &i.id,
            proposition: &i.proposition,
            pin: i.pin.as_deref(),
            scope: "WITHHELD",
        })
        .collect();
    serde_json::to_string_pretty(&json_items).expect("brief items are plain strings and always serialize")
}

/// The authoring rhythm brief — handed to whoever (person or agent) is
/// about to write a document with `tetel look`/`run`/`fact`/`claim`/
/// `prose`/`render`. This is the highest-evidence instruction this
/// project has: run twice against the same task and the same tool,
/// differing only in whether this text was given, it produced
/// interleaved composition and a claim revision triggered by writing
/// prose in one arm, and strict front-to-back transcription (gather
/// every fact, then every claim, then all the prose) in the other.
///
/// Adapted from the harness prototype's own working brief to name this
/// crate's actual subcommands, and to drop the two features that
/// prototype supported but this port does not (`tmove` reordering — see
/// `prose.rs`; `--before` insertion was later restored). Self-contained: it
/// names no other document, repository, or path.
pub const AUTHORING_BRIEF: &str = "\
# Working brief — writing with tetel

Write the document using tetel's authoring commands: `look`, `run`, `fact`,
`claim`, `prose`, `render`.

## The rhythm — this is how the tool is meant to be used

Do not gather all your facts, then write all your claims, then write all
your prose. Work in passes, and let the document grow alongside the
evidence:

- As soon as a claim exists that you can say something about, write that
  prose then — do not defer it to a writing phase at the end. Where it
  belongs in the finished document is a separate question from when you
  wrote it: `tetel prose --before <ID>` puts a block ahead of an existing
  one, so a paragraph discovered late can still open a section.
- When writing prose makes you realise a claim is imprecise, wrong, or
  needs a qualification, revise the claim (`tetel claim --revise`) and
  then revise the prose that cites it (`tetel prose --revise`).
- When you find you need evidence you do not have, go and get it —
  `tetel look`/`tetel run`/`tetel fact` mid-way through writing is normal
  and expected, not a failure of planning.

A run in which nothing is revised and prose is written only after the
last claim means the tool was used as a transcription buffer. That is a
legitimate outcome to report if it is what genuinely happened — but do
not aim for it.

## Grounding — where free reading stops

Orientation is free and unrecorded. Read however you like — grep around,
skim files, follow a call chain — to work out what you are even looking
at. None of that needs `look`/`run`.

But anything a fact rests on has to go *through* `look`/`run`, not just be
informed by it. Opening a file you already understood, only to give
`tetel fact` something to point at, records the act and throws away the
discovery it was supposed to be evidence of — the ledger shows a `look`,
not that it was theater.

`tetel fact` refuses on an empty pending buffer, so a fact minted with no
`look`/`run` at all is caught. It cannot tell a genuine discovery from a
`look` performed after the fact purely to satisfy that refusal — that
part is on you, not the tool.

## Spending evidence — the note is not the claim

Each of these is one observed failure from a real memo, turned into a
rule. Every one produced a defect that survived to a rendered document
and was caught later by a human reading closely.

- **A qualifier your note recorded is part of the fact.** If a note says
  `except` or `unless`, or records an ordering (`this runs AFTER that`),
  a claim resting on it either carries that qualifier or says why it is
  out of range. Writing `any`, `every` or `never` over a fact that
  recorded an exception is how a true fact becomes a false claim.

- **A comparison is a claim, not a note.** `X mirrors Y`, `both read the
  same field` — if this fact's extent contains only X, you have not read
  Y here. Mint a second fact for Y and put the comparison in a claim
  citing both. A note may name Y as context; it may not conclude about
  it. Two notes that each reach across to the other are how two facts
  come to contradict each other with nothing to notice it.

- **A number keeps the unit its instrument counted.** If the counter
  counted calls to one function, spend it as that. Converting it to
  another unit, or deriving a size from it, is a new assertion that needs
  its own claim or stays out of the prose.

- **A command that exits 0 has established nothing by exiting 0.** Before
  resting a fact on `run`, reread the transcript: does the output state
  the proposition, or only fail to deny it? If the proposition lives in a
  file the run wrote, that file belongs beside the memo, and the note
  says where.

Before `tetel render`, run `tetel review` and read each paragraph against
the claims it cites, asking one question: does this paragraph say
anything none of its cited claims says? The sentence carrying your
recommendation must cite a claim that states it, not a claim that happens
to sit nearby. Mint the missing claim or cut the sentence — do not let
the strongest sentence in the memo be the one with no row behind it.

Closing the loop is yours to do, not someone else's: once the document is
rendered (`tetel render`), run `tetel check` against it. That is your own
last check on what you just wrote, not a second reader's job.
";

#[cfg(test)]
mod tests {
    use super::*;
    use crate::ledger;

    #[test]
    fn authoring_brief_is_self_contained() {
        // This text ships in a public repository; it must never point at
        // a private planning repo, a path inside one, or any path at
        // all — a public reader has none of those to resolve.
        assert!(!AUTHORING_BRIEF.contains("lonic-planning"));
        assert!(!AUTHORING_BRIEF.contains("/Users/"));
        assert!(!AUTHORING_BRIEF.contains("/Volumes/"));
        assert!(!AUTHORING_BRIEF.contains("harness"));
        assert!(AUTHORING_BRIEF.contains("tetel claim --revise"));
        // The review step must stay named in the loop: `review` exists
        // to be run before `render`, and a brief that never mentions it
        // leaves the one channel that catches prose asserting past its
        // claims to be discovered by accident.
        assert!(AUTHORING_BRIEF.contains("tetel review"));
    }

    #[test]
    fn briefed_proposition_is_byte_identical_to_the_source_cell() {
        let body: Vec<String> = "\
| ID | Proposition | Domain | Extent | Kind | Status |
|---|---|---|---|---|---|
| X-1 | `foo`'s bundle is **never** streamed [X-2], per §3 | the whole module | opened in full | READING | **VERIFIED** |
"
        .lines()
        .map(str::to_string)
        .collect();
        let import = ledger::import(&body);
        assert!(import.errors.is_empty());
        let claim = &import.claims[0];
        let items = build(&import.claims);
        assert_eq!(items[0].proposition, claim.proposition);
        assert_eq!(
            items[0].proposition,
            "`foo`'s bundle is **never** streamed [X-2], per §3"
        );
    }

    #[test]
    fn text_render_never_mentions_domain_or_extent_content() {
        let body: Vec<String> = "\
| ID | Proposition | Domain | Extent | Kind | Status |
|---|---|---|---|---|---|
| X-1 | a proposition | UNIQUEDOMAINTOKEN | UNIQUEEXTENTTOKEN | READING | **VERIFIED** |
"
        .lines()
        .map(str::to_string)
        .collect();
        let import = ledger::import(&body);
        let items = build(&import.claims);
        let text = render_text("memo.md", &items);
        assert!(!text.contains("UNIQUEDOMAINTOKEN"));
        assert!(!text.contains("UNIQUEEXTENTTOKEN"));
        assert!(text.contains("scope: WITHHELD"));
    }

    #[test]
    fn json_render_never_mentions_domain_or_extent_content() {
        let body: Vec<String> = "\
| ID | Proposition | Domain | Extent | Kind | Status |
|---|---|---|---|---|---|
| X-1 | a proposition | UNIQUEDOMAINTOKEN | UNIQUEEXTENTTOKEN | READING | **VERIFIED** |
"
        .lines()
        .map(str::to_string)
        .collect();
        let import = ledger::import(&body);
        let items = build(&import.claims);
        let json = render_json(&items);
        assert!(!json.contains("UNIQUEDOMAINTOKEN"));
        assert!(!json.contains("UNIQUEEXTENTTOKEN"));
        let parsed: serde_json::Value = serde_json::from_str(&json).unwrap();
        assert_eq!(parsed[0]["scope"], "WITHHELD");
        assert_eq!(parsed[0]["id"], "X-1");
    }
}
