pub fn look_path(workspace_dir: &Path, path: &str, lines: Option<(usize, usize)>) -> Result<LookOutcome, AuthoringError> {
    let p = Path::new(path);
    if !p.exists() {
        return Err(workspace::refuse(workspace_dir, "look", format!("no such path: {path}")));
    }
    if p.is_dir() {
        return Err(workspace::refuse(
            workspace_dir,
            "look",
            format!(
                "{path} is a directory; `tetel look` opens files. Use `tetel look --grep <pattern> {path}` to search it."
            ),
        ));
    }
    let contents = fs::read_to_string(p).map_err(|e| AuthoringError::Io(e.to_string()))?;
    let key = resolve_key(p);
    // Resolved from the file being read, never from this process's working
    // directory — see `worldstate.rs` for the measurement that forced this.
    let world = worldstate::Session::new().for_path(p);

/// `tetel run <command...>` — executes `argv` directly (never through a
/// shell), prints its combined stdout/stderr, and records `argv`'s
/// command line plus the captured output into the pending buffer.
/// `run`'s own exit code mirrors the executed command's.
///
/// stdout and stderr are captured on separate pipes, each drained on
/// its own thread into one shared buffer, which reproduces `2>&1`'s
/// merged stream closely but not exactly: chunks from the two streams
/// can interleave in a different order than a real shell redirection
/// would produce, since nothing here observes their true fd-level
/// arrival order. Documented, not silently assumed exact.
pub fn run_command(workspace_dir: &Path, argv: &[String]) -> Result<RunOutcome, AuthoringError> {
    if argv.is_empty() {
        return Err(workspace::refuse(workspace_dir, "run", "no command given"));
    }
    // `run` is the one case where the process's own working directory is
    // the right answer rather than a fallback: a command names no path in
    // general, and it genuinely executed here.
    let world = worldstate::Session::new().for_cwd();
    let cmdline = argv.join(" ");

    let mut child = Command::new(&argv[0])
        .args(&argv[1..])
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|e| AuthoringError::Io(format!("could not run `{cmdline}`: {e}")))?;

    let captured = Arc::new(Mutex::new(Vec::<u8>::new()));

//! `tetel fact` — mints a fact from the pending observation buffer (see
//! `pending.rs`). Refuses on an empty buffer. There is deliberately no
//! flag anywhere on this module's CLI surface that lets a caller supply
//! the extent or captured output themselves — that absence is the
//! guarantee that a fact was actually backed by a `look`/`run`, not a
//! rule enforced after the fact.
//!
//! `tetel fact --revise <id> --why <text>` rewrites the note only,
//! append-only: extent, output and pin are set once at mint time and
//! never appear in a revision event at all, so there is no code path
//! that could change them later either.

//! `tetel brief` — the grounding brief: every claim's id and proposition,
//! byte-identical to the ledger cell it came from, with `domain`/`extent`
//! withheld entirely so an independent grounding pass can't see what the
//! author declared the claim ranges over. `BriefItem` carries no field a
//! scope could leak through — that's enforced by its shape, not by care
//! at render time.

use serde::Serialize;

use crate::ledger::Claim;

pub struct BriefItem {
    pub id: String,
    pub proposition: String,
    pub pin: Option<String>,
}

/// Every ledger claim, unconditionally — including one already grounded,
/// and including one grounded only by ingested (attested-derived)
/// evidence. Ingestion enrolls a claim in the independent-grounding loop;
/// it does not excuse it, so nothing here may drop a claim from the brief
/// on account of what its evidence ledger already holds. A claim leaves
/// this list only by leaving the ledger itself — never by having been
/// reported on.
pub fn build(claims: &[Claim]) -> Vec<BriefItem> {
    claims
        .iter()
        .map(|c| BriefItem {
            id: c.id.clone(),
            proposition: c.proposition.clone(),
            pin: c.pin.clone(),
        })
        .collect()
}

pub fn render_text(display_path: &str, items: &[BriefItem]) -> String {
    let mut out = String::new();
    out.push_str(&format!(
        "grounding brief: {display_path} — {} claim(s), scope withheld\n\n",
        items.len()
    ));
    for item in items {
        out.push_str(&format!("id: {}\n", item.id));
        out.push_str(&format!("proposition: {}\n", item.proposition));
        if let Some(pin) = &item.pin {
            out.push_str(&format!("pin: {pin}\n"));
        }
        out.push_str("scope: WITHHELD\n\n");
    }
    out
}

#[derive(Serialize)]
struct JsonItem<'a> {
    id: &'a str,
    proposition: &'a str,
    #[serde(skip_serializing_if = "Option::is_none")]
    pin: Option<&'a str>,
    scope: &'static str,
}

pub fn render_json(items: &[BriefItem]) -> String {
    let json_items: Vec<JsonItem> = items
        .iter()
        .map(|i| JsonItem {
            id: &i.id,
            proposition: &i.proposition,
            pin: i.pin.as_deref(),
            scope: "WITHHELD",
        })
        .collect();
    serde_json::to_string_pretty(&json_items).expect("brief items are plain strings and always serialize")
}

/// The authoring rhythm brief — handed to whoever (person or agent) is
/// about to write a document with `tetel look`/`run`/`fact`/`claim`/
/// `prose`/`render`. This is the highest-evidence instruction this
/// project has: run twice against the same task and the same tool,
/// differing only in whether this text was given, it produced
/// interleaved composition and a claim revision triggered by writing

/// add, run independently of the five `tetel`-row checks above: a claim
/// with no evidence record at all (human-owed — absence isn't a failure);
/// a claim grounded only by evidence that derives to `Attested` standing
/// (human-owed, and distinct from the first — someone looked,
/// off-instrument); and two verdicts that contradict each other, whether
/// that's two grounding passes disagreeing or a pass contradicting the
/// author's own `Status` cell (a machine failure — an unresolved
/// contradiction).
pub fn analyze_ledger(claims: &[Claim], evidence: &[EvidenceRecord]) -> LedgerFindings {
    let mut ungrounded = Vec::new();
    let mut attested_grounded = Vec::new();
    let mut disagreements = Vec::new();
    let mut qualified = Vec::new();
    let mut out_of_proof = Vec::new();
    let mut superseded = Vec::new();

    for claim in claims {
        let records: Vec<&EvidenceRecord> = evidence.iter().filter(|e| e.claim_id == claim.id).collect();

        // A record grades a *proposition*, not an id. The digest of the
        // text it graded is written into every record; comparing it to
        // the claim's current text is what stops evidence transferring to
        // a rewritten claim.
        //
        // Without this, revising a proposition through the ordinary
        // `claim --revise` + `render --out` path left its old evidence
        // attached — including to the exact negation of what was graded,
        // with the memo still matching its snapshot, no drift, and the
        // machine partition clean.
        //
        // **Whether a stale record fails depends on what sits beside it.**
        // The first version of this check failed on any stale record, and
        // that was undischargeable: the evidence log is append-only with
        // no supersession, so re-grounding — the remedy this very check
        // printed — added a current record and left the failure standing.
        // A red nobody can clear is the defect this crate rejected in the
        // verdict-disagreement check hours earlier, rebuilt here.
        //
        // So: a claim with no record matching its current text is a
        // machine failure, because nothing grades what it now says. A
        // claim that has one is grounded, and its superseded records are
        // history — worth printing, never a failure. Re-grounding is now
        // a remedy that works.
        let current = crate::evidence::sha256_hex(&claim.proposition);
        let (fresh, stale): (Vec<&&EvidenceRecord>, Vec<&&EvidenceRecord>) = records
            .iter()
            .filter(|r| !r.proposition_digest.is_empty())
            .partition(|r| r.proposition_digest == current);

        for r in &stale {
            let line = format!(
                "{} — evidence from pass {} graded different text than this claim now carries \
(recorded digest {}…, current {}…).\n      that pass said: {} — {}",
                claim.id,
                r.pass,
                &r.proposition_digest[..r.proposition_digest.len().min(12)],
                &current[..current.len().min(12)],
                r.verdict,
                r.note.as_deref().unwrap_or("(no note)"),
            );
            if fresh.is_empty() {
                out_of_proof.push(format!(
                    "{line}\n      Out of proof: nothing grades what this claim says today. \
Reprove it against the current wording, or restore the wording it was graded against."
                ));
            } else {
                superseded.push(format!(
                    "{line}\n      Superseded by a later proof: {} record(s) grade the current \
wording. Kept because it is what an earlier pass actually found, and the log is append-only.",
                    fresh.len()
                ));
            }
        }

        if records.is_empty() {
            ungrounded.push((claim.id.clone(), claim.proposition.clone()));
            continue;
        }

        // Every check below asks what the evidence says about *what this
        // claim says now*, so every one of them reads this set rather
        // than `records`.
        //
        // Making only the stale/superseded partition digest-aware and
        // leaving the verdict checks comparing all records was the same
        // defect one layer down, and it punished exactly the loop this
        // crate exists to produce: a pass refutes a claim, the author
        // fixes the wording, a later pass grounds the new wording
        // unanimously — and `verdict-disagreement` still fired, forever,
        // on a supports/refutes pair against text that no longer exists.
        // The only escape was withdrawing the claim and re-issuing it
        // under a fresh id, which erases the refutation from the rendered
        // ledger — the one trail the loop exists to preserve. An
        // undischargeable red that can only be cleared by destroying
        // evidence is worse than the one it replaced.
        //
        // A record with no digest at all predates the field. It is
        // treated as grading the current text rather than dropped:
        // dropping it would silently retire these checks for every
        // document written before digests existed, turning a live
        // contradiction into a clean report. Grandfathering can at worst
        // report a disagreement that a revision has since resolved —
        // which is the direction that fails loudly.
        let grading_current: Vec<&EvidenceRecord> = records
            .iter()
            .copied()
            .filter(|r| r.proposition_digest.is_empty() || r.proposition_digest == current)
            .collect();

        // Distinct from "ungrounded": at least one record grades the
        // current text, and every one that does derives to `Attested` for
        // standing purposes. Today that's unconditionally true — ingestion
        // is the only write path, and `derived_kind` never returns
        // anything else for an ingested record — but the check is written
        // against `derived_kind`, not against "has any evidence", so it
        // keeps working once a witnessed grounding can also land here.
        //
        // The emptiness guard is not redundant: a claim whose records all
        // grade superseded text has already been reported as a machine
        // failure by the partition above, and `all` over nothing is true,
        // so without it that claim would also be announced as grounded.
        if !grading_current.is_empty() && grading_current.iter().all(|r| r.derived_kind() == Kind::Attested) {
            attested_grounded.push((claim.id.clone(), claim.proposition.clone()));
        }

        // A contradiction is `supports` *and* `refutes` on one
        // proposition — P and not-P, decidable without a human, which is
        // what belongs in the machine partition.
        //
        // Two things this deliberately no longer does.
        //

/// One evidence record, as read back out of `<memo>.evidence.jsonl` for
/// use by `tetel check`.
#[derive(Debug, Clone)]
pub struct EvidenceRecord {
    pub claim_id: String,
    pub verdict: Verdict,
    pub pass: String,
    /// What the reporter said this act was. Carried for fidelity and
    /// display; deliberately *not* read by [`EvidenceRecord::derived_kind`].
    #[allow(dead_code)] // carried for fidelity; no check reasons over its value directly — see derived_kind
    pub reported_kind: String,
    /// Where the act is recorded — a file path, or `proc:<session-or-agent>`.
    /// Read by `checks::unresolved_evidence_sources`.
    pub source: String,
    #[allow(dead_code)] // carried for fidelity; no check reasons over it yet
    pub extent: Vec<String>,
    pub note: Option<String>,
    #[allow(dead_code)] // carried for fidelity; no check reasons over it yet
    pub pin: Option<String>,
    #[allow(dead_code)] // carried for fidelity; no check reasons over it yet
    pub timestamp: u64,
    /// True when this record's predicate type is
    /// [`CAPTURED_PREDICATE_TYPE`] — its extent was copied from a fact
    /// this tool captured, not typed by a caller. The one bit that
    /// separates "the tool witnessed the act" from "the tool witnessed
    /// someone saying the act happened".
    pub witnessed: bool,
    /// sha256 of the exact proposition text this record was graded
    /// against, read back from `subject.digest`.
    ///
    /// Written since this module existed and, until now, read by nothing.
    /// A record is matched to a claim by **id**, so a proposition could
    /// be revised underneath its own evidence and the evidence would
    /// silently transfer — including to its negation, through the
    /// ordinary `claim --revise` + `render` path, with the memo still
    /// matching its snapshot and the machine partition still clean.
    /// [`crate::checks::analyze_ledger`] now compares this against the
    /// claim's current text, which is what the field was for.
    pub proposition_digest: String,
}

impl EvidenceRecord {
    /// The kind this record counts as for anything that derives a claim's
    /// standing — always [`Kind::Attested`], regardless of what
    /// `reported_kind` says.
    ///
    /// This is deliberate, not a stub: the reporter states what kind of
    /// act it was, but the tool witnessed only the *saying*, never the
    /// act — a report of a run is not a run. Treating every ingested
    /// record as `Attested` for standing is what keeps ingestion from
    /// moving a claim above "vouched" (permanently human-owed): reading,
    /// observed and attested rows all cap out there, and this method's
    /// whole job is to make sure a reported `run` can't sneak past that
    /// cap by claiming a stronger kind than the tool ever saw for itself.
    pub fn derived_kind(&self) -> Kind {
        if self.witnessed {
            // The extent came from a fact this tool captured itself, so
            // the act is one it saw. `Run` is the strongest standing this
            // crate has, and this is the only path that can reach it.
            Kind::Run
        } else {
            Kind::Attested
        }
    }
}

pub fn sha256_hex(data: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(data.as_bytes());
    hasher.finalize().iter().map(|b| format!("{b:02x}")).collect()
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
}

